"""Reusable, server-rendered editorial components; no browser framework required."""
import json
from html import escape as e
from pathlib import Path
from PIL import Image
ROOT = Path(__file__).resolve().parents[1]
P = json.loads((ROOT/'data/project.json').read_text(encoding='utf-8-sig'))
def image(name, alt, cls='', eager=False, sizes='100vw'):
    path = f'assets/img/{name}-1280.webp'
    w,h = Image.open(ROOT/path).size
    srcset = f'assets/img/{name}-640.webp 640w, {path} {w}w'
    if (ROOT/f'assets/img/{name}-1600.webp').exists(): srcset += f', assets/img/{name}-1600.webp 1600w'
    return f'<img class="{cls}" src="{path}" srcset="{srcset}" sizes="{sizes}" width="{w}" height="{h}" alt="{e(alt)}" loading="{"eager" if eager else "lazy"}" decoding="async" {"fetchpriority=high" if eager else ""}>'
MARK = (ROOT/'assets/img/logo-mark.svg').read_text(encoding='utf-8').replace('role="img" aria-label="Valencia Town"','aria-hidden="true" focusable="false"')
def todo(value, fallback='To be confirmed'):
    return f'<span class="tbc">{fallback}</span>' if str(value).startswith('TODO') else e(str(value))
MAHAKAL_ART = (ROOT/'assets/img/mahakal-line.svg').read_text(encoding='utf-8').replace('<svg ','<svg class="mahakal-svg" ',1)
def phone_href(): return 'tel:+' + ''.join(ch for ch in P['SALES_PHONE'] if ch.isdigit())
