    return f'''<section class="gallery" id="gallery" aria-labelledby="gallery-title"><div class="wrap gallery-head"><h2 id="gallery-title" class="display display-s">A closer look.</h2><p class="lede">Four views of the township as it is planned. Tap any image to see it in full.</p></div><div class="gallery-strip">{''.join(f'<figure class="gallery-item"><button data-gallery="{i}" aria-label="Enlarge {alt.lower()}">{image(img,alt,sizes="(max-width: 767px) 86vw, 62vw")}</button><figcaption>{alt}</figcaption></figure>' for i,(img,alt) in enumerate(assets))}</div></section>'''
