def developer():
    D=P['developer']
    if str(D['name']).startswith('TODO'): return ''
    tes=[t for t in P['testimonials'] if not str(t['quote']).startswith('TODO')]
    tes_html=''.join('<blockquote><p>“'+e(t['quote'])+'”</p><footer>'+e(t['name'])+'<span>'+e(t['detail'])+'</span></footer></blockquote>' for t in tes)
    rows=[('Past projects',', '.join(todo(x) for x in D['pastProjects'])),('Construction status',todo(D['constructionStatus'])),('Possession',todo(D['possession'])),('Bank tie-ups',', '.join(todo(x) for x in D['bankTieUps'])),('Sales gallery',todo(D['salesGallery'])+'<br>'+e(D['hours']))]
    return f'''<section class="developer" id="developer" aria-labelledby="developer-title"><div class="wrap faq-grid"><div class="faq-intro"><h2 id="developer-title" class="display display-s">Built by people<br>who stay.</h2><p class="lede">{todo(D['name'])}, part of {todo(D['group'])}. Developing in the region since {todo(D['since'])}.</p></div><dl class="facts-list">{''.join(f'<div><dt>{k}</dt><dd>{v}</dd></div>' for k,v in rows)}</dl></div>{('<div class="wrap testimonials">'+tes_html+'</div>') if tes else ''}</section>'''
