def document():
    url=SITE_URL; description=f'Valencia, The Address of Tomorrow: {P["acres"]} acres of residential plots at Shahna on the Indore–Ujjain Road, forty minutes from Shri Mahakaleshwar, Ujjain. Mahakal is calling you home.'
    schema={'@context':'https://schema.org','@graph':[{'@type':'Place','name':P['name'],'url':url+'/', 'description':description,'address':{'@type':'PostalAddress','streetAddress':'Indore–Ujjain Road','addressLocality':'Shahna','addressRegion':'Madhya Pradesh','addressCountry':'IN'},'geo':{'@type':'GeoCoordinates','latitude':P['latitude'],'longitude':P['longitude']}},{'@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in faqs()]}]}
    head=f'''<!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><title>Valencia | The Address of Tomorrow</title><meta name="description" content="{description}"><meta name="theme-color" content="#17231D"><meta name="robots" content="index, follow, max-image-preview:large"><link rel="canonical" href="{url}/"><meta property="og:type" content="website"><meta property="og:locale" content="en_IN"><meta property="og:site_name" content="Valencia Town"><meta property="og:title" content="Valencia — The Address of Tomorrow"><meta property="og:description" content="{description}"><meta property="og:url" content="{url}/"><meta property="og:image" content="{url}/assets/img/og-image.jpg"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="Valencia — The Address of Tomorrow"><meta name="twitter:description" content="{description}"><meta name="twitter:image" content="{url}/assets/img/og-image.jpg"><link rel="icon" href="assets/img/favicon.svg" type="image/svg+xml"><link rel="icon" href="assets/img/favicon.ico" sizes="32x32"><link rel="apple-touch-icon" href="assets/img/apple-touch-icon.png"><link rel="preload" href="assets/fonts/cormorant.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="assets/fonts/cormorant-italic.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="assets/fonts/dmsans.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" as="image" href="assets/img/hero-signage-1280.webp" imagesrcset="assets/img/hero-signage-640.webp 640w, assets/img/hero-signage-1280.webp 1280w" imagesizes="100vw" media="(min-width: 768px)" fetchpriority="high"><link rel="stylesheet" href="css/style.css?v=20261010f"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></head>'''
    return head+'<body>'+header()+'<main id="main">'+''.join(f() for f in [hero,mahakal,location,plan,life,gallery,plots,visit,faq,developer])+'</main>'+footer()+modals()+f'<script id="project-data" type="application/json">{json.dumps(P,ensure_ascii=False).replace("<","&lt;")}</script><script src="js/main.js?v=20261010f" defer></script></body></html>'
